'use strict';

const prepareError = err => {
    if (!err || !err.stack) {
        return err;
    }

    const obj = {
        name: err.name || err.constructor.name,
        message: err.message,
        stack: err.stack,
    };

    if (err.cause) {
        const cause = prepareError(err.cause);
        if (cause) {
            obj.cause = cause;
        }
    }

    const keys = Object.keys(err);
    for (let key of keys) {
        if (obj[key] === undefined) {
            obj[key] = err[key];
        }
    }

    return obj;
};

const normalizeErrorsInObject = (obj, visited = new WeakSet()) => {
    if (obj === null || typeof obj !== 'object' || visited.has(obj)) {
        return;
    }

    visited.add(obj);

    if (obj instanceof Error) {
        return prepareError(obj);
    }

    for (const key in obj) {
        if (Object.prototype.hasOwnProperty.call(obj, key)) {
            const value = obj[key];

            if (value instanceof Error) {
                obj[key] = prepareError(value);
            } else if (value && typeof value === 'object') {
                normalizeErrorsInObject(value, visited);
            }
        }
    }
};

/**
 * Преобразует объекты Error из свойств record
 *
 * Сохраняет любые нестандартные перечисляемые поля, плюс базовые:
 *   - cause
 *   - name
 *   - message
 *   - stack
 *
 * @returns {Function}
 */
module.exports = () => {
    /**
     * @param {Object} record
     * @returns {undefined}
     */
    return record => {
        normalizeErrorsInObject(record);
    };
};
